#include "../src/platform/game_audio.hpp"
#include <chrono>
#include <iostream>
int main(int argc,char**argv){if(argc!=2)return 1;shin::platform::GameAudio a(argv[1],false);if(!a.load_inmm_playlist()||!a.prepare_track(2)||!a.play_track(2))return 2;auto pump=[&]{MSG m;while(PeekMessageW(&m,nullptr,0,0,PM_REMOVE)){TranslateMessage(&m);DispatchMessageW(&m);}a.service_music();Sleep(2);};auto ready=[&]{auto t=std::chrono::steady_clock::now();while(!a.music_playing()&&std::chrono::steady_clock::now()-t<std::chrono::seconds(5))pump();return a.music_playing();};if(!ready())return 3;if(!a.prepare_track(4))return 7;auto t=std::chrono::steady_clock::now();if(!a.play_track(4))return 4;double request=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-t).count();if(!ready())return 5;pump();bool handoff=false;for(auto&e:a.events())handoff|=e.action=="music_handoff";if(!handoff)return 6;if(!a.prepare_track(3))return 8;a.stop_music();if(a.music_playing()||a.active_track()!=0)return 9;std::cout<<"request_ms="<<request<<" handoff_ready_ms="<<std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-t).count()<<" retained previous playback until new player PLAYING\n";}
